<?php
defined('ABSPATH') || exit;
function tkcsky_is_form($f=null){$f=$f?:(class_exists('WPCF7_ContactForm')?WPCF7_ContactForm::get_current():null);return $f&&in_array((int)$f->id(),array_map('intval',get_option('tkcsky_forms',[])),true);}
function tkcsky_form_lang($f){$forms=get_option('tkcsky_forms',[]);return (int)($forms['et']??0)===(int)$f->id()?'et':'en';}
function tkcsky_photo_path($entry,$thumb=false){if(get_post_type($entry)!=='flamingo_inbound'||!get_post_meta($entry,'_tkcsky_project',true))return false;$name=get_post_meta($entry,$thumb?'_tkcsky_thumb':'_tkcsky_photo',true);if(!is_string($name)||!preg_match('/^[a-f0-9]{48}\.jpg$/D',$name))return false;$dir=tkcq_private_dir();return !is_wp_error($dir)&&is_file($dir.'/'.$name)?$dir.'/'.$name:false;}
function tkcsky_photo_url($id,$private=false){$url=add_query_arg(['action'=>$private?'tkcsky_private_photo':'tkcsky_photo','entry'=>(int)$id],admin_url('admin-post.php'));return $private?wp_nonce_url($url,'tkcsky_photo_'.$id):$url;}
function tkcsky_serve_photo($private=false){
 $id=absint($_GET['entry']??0);$project=(int)get_post_meta($id,'_tkcsky_project',true);$allowed=false;
 if($private)$allowed=current_user_can('edit_pages')&&wp_verify_nonce(sanitize_text_field(wp_unslash($_GET['_wpnonce']??'')),'tkcsky_photo_'.$id)&&get_post_status($id)!=='trash';
 else $allowed=get_post_status($id)==='publish'&&get_post_type($project)==='tkc_online'&&get_post_status($project)==='publish'&&get_post_meta($id,'_tkcsky_review',true)==='approved'&&get_post_meta($id,'_tkcsky_consent',true)==='public-v1'&&(int)get_post_meta($id,'_tkcsky_published_at',true)>0;
 $path=$allowed?tkcsky_photo_path($id,($_GET['size']??'')==='thumb'):false;
 nocache_headers();header('Cache-Control: private, no-store, max-age=0');header('X-Content-Type-Options: nosniff');header('X-Robots-Tag: noindex, noarchive');if(!$path){status_header(404);exit('Photo not found.');}
 header('Content-Type: image/jpeg');header('Content-Disposition: inline; filename="the-sky-the-city.jpg"');header('Content-Length: '.filesize($path));readfile($path);exit;
}
add_action('admin_post_tkcsky_photo',function(){tkcsky_serve_photo();});add_action('admin_post_nopriv_tkcsky_photo',function(){tkcsky_serve_photo();});
add_action('admin_post_tkcsky_private_photo',function(){tkcsky_serve_photo(true);});add_action('admin_post_nopriv_tkcsky_private_photo',function(){nocache_headers();status_header(404);exit('Photo not found.');});
add_action('before_delete_post',function($id){if(!get_post_meta($id,'_tkcsky_project',true))return;foreach([false,true]as$thumb){$path=tkcsky_photo_path($id,$thumb);if($path)wp_delete_file($path);}});
add_filter('wpcf7_form_hidden_fields',function($fields){if(empty($GLOBALS['tkcsky_context'])||!tkcsky_is_form())return $fields;$ctx=$GLOBALS['tkcsky_context'];$expires=time()+DAY_IN_SECONDS;$fields['tkcsky_id']=$ctx['id'];$fields['tkcsky_expires']=$expires;$fields['tkcsky_signature']=hash_hmac('sha256',$ctx['id'].'|'.$ctx['form'].'|'.$expires.'|public-v1',wp_salt('auth'));if(is_user_logged_in())$fields['_wpnonce']=wp_create_nonce('wp_rest');return $fields;});
function tkcsky_submitted_project($s,$f){$id=absint($s->get_posted_data('tkcsky_id'));$expires=absint($s->get_posted_data('tkcsky_expires'));$signature=(string)$s->get_posted_data('tkcsky_signature');$expected=hash_hmac('sha256',$id.'|'.$f->id().'|'.$expires.'|public-v1',wp_salt('auth'));return $expires>=time()&&$expires<=time()+2*DAY_IN_SECONDS&&hash_equals($expected,$signature)&&tkcsky_open($id)?$id:0;}
add_filter('wpcf7_validate',function($result,$tags){if(!tkcsky_is_form())return $result;$f=WPCF7_ContactForm::get_current();$s=WPCF7_Submission::get_instance();if(!$s||!tkcsky_submitted_project($s,$f))foreach($tags as$tag)if($tag->name==='sky-nickname'){$result->invalidate($tag,tkcsky_form_lang($f)==='et'?'Vorm on aegunud või projekt on suletud. Palun värskenda lehte.':'The form has expired or submissions are closed. Please refresh the page.');break;}return $result;},30,2);
add_filter('wpcf7_skip_mail',function($skip,$f){return tkcsky_is_form($f)?true:$skip;},100,2);
add_filter('wpcf7_flamingo_submit_if',function($statuses){return tkcsky_is_form()?[]:$statuses;},110);
add_action('wpcf7_before_send_mail',function($f,&$abort,$s){
 if(!tkcsky_is_form($f))return;$id=tkcsky_submitted_project($s,$f);$et=tkcsky_form_lang($f)==='et';$entry_id=0;$names=[];$lock='';
 try{
  if(!$id||!class_exists('Flamingo_Inbound_Message'))throw new RuntimeException($et?'Fotode saatmine ei ole saadaval. Palun värskenda lehte.':'Submissions are unavailable. Please refresh the page.');
  $email=trim((string)$s->get_posted_data('sky-email'));$nickname=sanitize_text_field((string)$s->get_posted_data('sky-nickname'));$city=sanitize_text_field((string)$s->get_posted_data('sky-city'));$message=sanitize_textarea_field((string)$s->get_posted_data('sky-message'));
  if(!$email||!is_email($email)||sanitize_email($email)!==$email||strlen($email)>254||!$nickname||mb_strlen($nickname)>80||!$city||mb_strlen($city)>120||mb_strlen($message)>200)throw new RuntimeException($et?'Palun kontrolli sisestatud välju.':'Please check the form fields and text lengths.');
  if(!in_array('1',array_map('strval',(array)$s->get_posted_data('sky-public')),true)||trim((string)$s->get_posted_data('tkc-website'))!=='')throw new RuntimeException($et?'Palun kinnita avaldamise nõusolek.':'Please confirm your permission for public display.');
  $files=$s->uploaded_files();$file=$files['sky-photo']??[];$file=is_array($file)?$file:[$file];if(count($file)!==1||!is_file($file[0])||filesize($file[0])>5*MB_IN_BYTES)throw new RuntimeException($et?'Lisa üks JPG-, PNG- või WebP-foto, kuni 5 MB.':'Attach one JPG, PNG or WebP photo, up to 5 MB.');
  $mime=wp_get_image_mime($file[0]);if(!in_array($mime,['image/jpeg','image/png','image/webp'],true))throw new RuntimeException($et?'Toetatud on JPG, PNG ja WebP.':'Please use JPG, PNG or WebP.');
  $rate='tkcsky_rate_'.hash_hmac('sha256',(string)($_SERVER['REMOTE_ADDR']??'unknown'),wp_salt('auth'));$count=(int)get_transient($rate);if($count>=15)throw new RuntimeException($et?'Liiga palju katseid. Proovi 15 minuti pärast uuesti.':'Too many uploads. Please try again in 15 minutes.');set_transient($rate,$count+1,15*MINUTE_IN_SECONDS);
  $fingerprint=hash_hmac('sha256',wp_json_encode([$id,strtolower($email),$nickname,$city,$message,hash_file('sha256',$file[0])]),wp_salt('nonce'));$existing=get_posts(['post_type'=>'flamingo_inbound','post_status'=>'publish','numberposts'=>1,'lang'=>'','suppress_filters'=>true,'meta_key'=>'_tkcsky_fingerprint','meta_value'=>$fingerprint]);if($existing&&tkcsky_photo_path($existing[0]->ID))return;
  $lock='tkcsky_lock_'.$fingerprint;$old=(int)get_option($lock);if($old&&$old<time()-600)delete_option($lock);if(!add_option($lock,time(),'','no')){$lock='';throw new RuntimeException($et?'Fotot juba töödeldakse. Palun oota.':'This photo is already being processed. Please wait.');}
  $photo=tkcq_store_photo($file[0]);if(is_wp_error($photo))throw new RuntimeException($photo->get_error_message());$names[]=$photo;$dir=tkcq_private_dir();$editor=wp_get_image_editor($dir.'/'.$photo);if(is_wp_error($editor))throw new RuntimeException('Photo preview could not be prepared.');$resize=$editor->resize(900,900,false);if(is_wp_error($resize))throw new RuntimeException('Photo preview could not be resized.');$thumb=bin2hex(random_bytes(24)).'.jpg';$saved=$editor->save($dir.'/'.$thumb,'image/jpeg');if(is_wp_error($saved))throw new RuntimeException('Photo preview could not be saved.');$names[]=$thumb;if(class_exists('Imagick')){$clean=new Imagick($dir.'/'.$thumb);$clean->stripImage();$clean->writeImage($dir.'/'.$thumb);$clean->clear();}@chmod($dir.'/'.$thumb,0640);
  if(!tkcsky_open($id))throw new RuntimeException('Submissions are closed.');
  $entry=Flamingo_Inbound_Message::add(['channel'=>'tkc-sky-city','status'=>'mail_sent','subject'=>get_the_title($id).' — '.$city,'from'=>$nickname,'from_name'=>$nickname,'from_email'=>'','fields'=>['nickname'=>$nickname,'email'=>$email,'city'=>$city,'message'=>$message,'photo'=>'Open in Online projects / Submissions'],'meta'=>['sky_project'=>$id,'language'=>tkcsky_form_lang($f)],'consent'=>[],'timestamp'=>time()]);
  $entry_id=method_exists($entry,'id')?(int)$entry->id():(int)$entry->id;if(!$entry_id)throw new RuntimeException('Your photo could not be saved.');
  foreach(['project'=>$id,'nickname'=>$nickname,'email'=>$email,'city'=>$city,'message'=>$message,'photo'=>$photo,'thumb'=>$thumb,'review'=>'pending','consent'=>'public-v1','consent_at'=>gmdate('c'),'language'=>tkcsky_form_lang($f),'fingerprint'=>$fingerprint]as$key=>$value)update_post_meta($entry_id,'_tkcsky_'.$key,$value);
  if((int)get_post_meta($entry_id,'_tkcsky_project',true)!==$id||!tkcsky_photo_path($entry_id)||!tkcsky_photo_path($entry_id,true))throw new RuntimeException('Your photo could not be saved. Please try again.');
 }catch(Throwable $e){$abort=true;$s->set_response($e->getMessage());if($entry_id)wp_trash_post($entry_id);$dir=tkcq_private_dir();if(!is_wp_error($dir))foreach($names as$name)if(preg_match('/^[a-f0-9]{48}\.jpg$/D',$name))wp_delete_file($dir.'/'.$name);}
 finally{if($lock)delete_option($lock);}
},20,3);
